/// <reference types="react" />
import type { CellContext } from '@tanstack/react-table';
import type { AvatarProps } from '../../../Avatar/Avatar.types';
/**
 * Props for AvatarCell component
 * @template TData - The type of data in the table row
 * @template TValue - The type of value in this cell (typically string for userName)
 */
export interface IAvatarCellProps<TData, TValue> {
    /** Cell context from TanStack React Table */
    cell: CellContext<TData, TValue>;
    /**
     * Additional Avatar props to customize the avatar appearance.
     * Cell value is always used as userName for initials/fallback.
     * For image type, pass src via avatarProps.
     */
    avatarProps?: Partial<Omit<AvatarProps, 'userName'>>;
}
/**
 * AvatarCell renders an Avatar component within a table cell.
 * The cell value is used as the userName prop for generating initials
 * and providing fallback text for accessibility.
 *
 * @example
 * ```tsx
 * // Basic initials avatar
 * {
 *   accessorKey: 'fullName',
 *   header: 'User',
 *   cell: (cell) => <AvatarCell cell={cell} />,
 * }
 *
 * // Image avatar with src from another field
 * {
 *   accessorKey: 'fullName',
 *   header: 'User',
 *   cell: (cell) => (
 *     <AvatarCell
 *       cell={cell}
 *       avatarProps={{
 *         type: 'image',
 *         src: cell.row.original.profileImageUrl,
 *       }}
 *     />
 *   ),
 * }
 *
 * // Custom size avatar
 * {
 *   accessorKey: 'fullName',
 *   header: 'User',
 *   cell: (cell) => (
 *     <AvatarCell cell={cell} avatarProps={{ size: 'small' }} />
 *   ),
 * }
 * ```
 */
type AvatarCellComponent = {
    <TData, TValue>(props: IAvatarCellProps<TData, TValue>): JSX.Element;
    displayName?: string;
};
export declare const AvatarCell: AvatarCellComponent;
export {};
